/**
 * Starlight route middleware (registered with `routeMiddleware` in astro.config.mjs).
 *
 * Adds <link rel="alternate" type="text/markdown"> pointing at the page's Markdown
 * twin (generated by src/pages/[...slug].md.ts), so an agent that lands on an HTML
 * page can find the clean version. Starlight's own 404 route has no twin.
 *
 * This edits route data instead of overriding the <Head> component on purpose:
 * starlight-theme-black 0.7 overrides <Head> itself (to load its fonts), and a
 * user-level override would make the theme skip its own.
 * See https://starlight.astro.build/guides/route-data/
 */
import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { markdownUrl } from './urls';

export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  if (route.id === '404') return;
  const site = context.site ?? new URL(context.url.origin);
  route.head.push({
    tag: 'link',
    attrs: { rel: 'alternate', type: 'text/markdown', href: markdownUrl(route.id, site), title: 'Markdown' },
  });
});
